const TYPES={
  electric:{label:'Elettrica',color:'#69e5dd'},hybrid:{label:'Ibrida',color:'#f4cb58'},diesel:{label:'Diesel',color:'#75a8ff'},petrol:{label:'Benzina',color:'#f89562'}
};
const DEFAULTS={
  city:{electric:[15.5,380,650],hybrid:[4.5,520,760],diesel:[4.8,620,790],petrol:[6.1,600,750]},
  sport:{electric:[21,620,1450],hybrid:[7.1,800,1550],diesel:[6.4,880,1500],petrol:[9.2,980,1600]},
  suv:{electric:[20,520,1050],hybrid:[6.2,680,1160],diesel:[6.5,760,1150],petrol:[8.3,780,1200]},
  van:{electric:[23,560,1050],hybrid:[7.0,730,1150],diesel:[7.2,800,1100],petrol:[9.5,820,1160]}
};
let state={segment:'city',data:structuredClone(DEFAULTS)};
const $=id=>document.getElementById(id); const fmt=new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',maximumFractionDigits:0});
const num=id=>Math.max(0,parseFloat($(id).value)||0);
function energyCost(type,consumption,km){if(type==='electric'){const blended=(num('homePrice')*num('homeShare')+num('publicPrice')*(100-num('homeShare')))/100;return km/100*consumption*blended} const price=type==='diesel'?num('dieselPrice'):num('petrolPrice');return km/100*consumption*price}
function calculate(){const km=num('kmRange'),years=Math.max(1,num('years'));$('kmOutput').value=km.toLocaleString('it-IT')+' km';const rows=Object.entries(TYPES).map(([key,type])=>{const [cons,maint,other]=state.data[state.segment][key];const energy=energyCost(key,cons,km);return{key,...type,cons,maint,other,energy,total:energy+maint+other}});const min=Math.min(...rows.map(x=>x.total)),max=Math.max(...rows.map(x=>x.total));$('cards').innerHTML=rows.map(r=>`<article class="cost-card ${r.total===min?'best':''}" style="--card-color:${r.color}"><div class="vehicle-title"><span class="dot"></span><h3>${r.label}</h3></div><div class="annual">${fmt.format(r.total)} <small>/ anno</small></div><div class="monthly">${fmt.format(r.total/12)} al mese · ${fmt.format(r.total*years)} in ${years} ${years===1?'anno':'anni'}</div><div class="per-km"><span>Costo al km</span><b>${(r.total/km).toLocaleString('it-IT',{style:'currency',currency:'EUR',minimumFractionDigits:2,maximumFractionDigits:2})}</b></div><div class="saving">${r.total===min?`Risparmi ${fmt.format(Math.max(...rows.map(x=>x.total))-r.total)} sul più costoso`:''}</div></article>`).join('');$('chart').innerHTML=rows.map(r=>`<div class="bar-row" style="--card-color:${r.color}"><span>${r.label}</span><div class="bar-bg"><div class="bar-energy" style="width:${r.energy/max*100}%" title="Energia: ${fmt.format(r.energy)}"></div><div class="bar-fixed" style="width:${(r.maint+r.other)/max*100}%" title="Gestione: ${fmt.format(r.maint+r.other)}"></div></div><span class="bar-total">${fmt.format(r.total)}</span></div>`).join('')+'<div class="legend"><span>Energia</span><span>Gestione</span></div>';}
function renderTable(){const unit=k=>k==='electric'?'kWh/100 km':'l/100 km';$('assumptionRows').innerHTML=Object.entries(TYPES).map(([key,t])=>{const v=state.data[state.segment][key];return `<tr><td><span class="dot" style="display:inline-block;--card-color:${t.color};margin-right:8px"></span>${t.label}</td><td><input data-type="${key}" data-index="0" type="number" min="0" step="0.1" value="${v[0]}"> ${unit(key)}</td><td><input data-type="${key}" data-index="1" type="number" min="0" step="10" value="${v[1]}"> €/anno</td><td><input data-type="${key}" data-index="2" type="number" min="0" step="10" value="${v[2]}"> €/anno</td></tr>`}).join('');document.querySelectorAll('tbody input').forEach(el=>el.addEventListener('input',e=>{state.data[state.segment][e.target.dataset.type][+e.target.dataset.index]=Math.max(0,+e.target.value||0);calculate()}))}
document.querySelectorAll('.segment').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.segment').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-checked','false')});btn.classList.add('active');btn.setAttribute('aria-checked','true');state.segment=btn.dataset.segment;renderTable();calculate()}));
['kmRange','years','homeShare','petrolPrice','dieselPrice','homePrice','publicPrice'].forEach(id=>$(id).addEventListener('input',calculate));
$('resetBtn').addEventListener('click',()=>{state.data=structuredClone(DEFAULTS);$('kmRange').value=15000;$('years').value=5;$('homeShare').value=80;$('petrolPrice').value=2.108;$('dieselPrice').value=2.227;$('homePrice').value=.28;$('publicPrice').value=.65;renderTable();calculate()});
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('installBtn').hidden=false});$('installBtn').addEventListener('click',async()=>{if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('installBtn').hidden=true}});if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js'));
renderTable();calculate();
